/* UI and SVG drawing; binary inference and geometry live in svm.js. */
'use strict';
let model,lastResult;
const $=id=>document.getElementById(id),NS='http://www.w3.org/2000/svg';
function svgEl(tag,attrs,text){const el=document.createElementNS(NS,tag);for(const[k,v]of Object.entries(attrs))el.setAttribute(k,v);if(text!==undefined)el.textContent=text;return el;}
function drawGraph(result){
 const svg=$('svm-graph');svg.replaceChildren();
 const project=SimpleSvm.projection(result.z,model),points=model.training_examples.map(row=>row.z),all=[...points,result.z,...(project?[project]:[])];
 const min=Math.floor(Math.min(-2,...all.flat())-.5),max=Math.ceil(Math.max(2,...all.flat())+.5),size=520,left=80,top=40;
 const sx=x=>left+(x-min)/(max-min)*size,sy=y=>top+size-(y-min)/(max-min)*size;
 svg.append(svgEl('rect',{x:0,y:0,width:660,height:660,fill:'white'}));
 function clipPolygon(poly,a,b,c){const out=[];for(let i=0;i<poly.length;i++){const p=poly[i],q=poly[(i+1)%poly.length],fp=a*p[0]+b*p[1]+c,fq=a*q[0]+b*q[1]+c;if(fp<=0)out.push(p);if((fp<=0)!==(fq<=0)){const t=fp/(fp-fq);out.push([p[0]+t*(q[0]-p[0]),p[1]+t*(q[1]-p[1])]);}}return out;}
 const [a,b]=model.weights,c=model.bias,box=[[min,min],[max,min],[max,max],[min,max]];
 const polygon=(p,fill)=>{if(p.length)svg.append(svgEl('polygon',{points:p.map(v=>sx(v[0])+','+sy(v[1])).join(' '),fill}));};
 polygon(clipPolygon(box,a,b,c),'#edf4fa');polygon(clipPolygon(box,-a,-b,-c),'#fcf0f2');polygon(clipPolygon(clipPolygon(box,a,b,c-1),-a,-b,-c-1),'#fff2d0');
 const step=Math.max(1,Math.ceil((max-min)/8));for(let v=min;v<=max;v+=step){svg.append(svgEl('line',{x1:sx(v),y1:top,x2:sx(v),y2:top+size,stroke:'#dbe4e2','stroke-width':1}));svg.append(svgEl('line',{x1:left,y1:sy(v),x2:left+size,y2:sy(v),stroke:'#dbe4e2','stroke-width':1}));svg.append(svgEl('text',{x:sx(v),y:top+size+24,'text-anchor':'middle',fill:'#536971'},v));svg.append(svgEl('text',{x:left-12,y:sy(v)+4,'text-anchor':'end',fill:'#536971'},v));}
 function line(target){const hits=[],eps=1e-8;function add(x,y){if(x>=min-eps&&x<=max+eps&&y>=min-eps&&y<=max+eps&&!hits.some(p=>Math.hypot(p[0]-x,p[1]-y)<eps))hits.push([x,y]);}if(Math.abs(b)>eps){for(const x of [min,max])add(x,(target-c-a*x)/b);}if(Math.abs(a)>eps){for(const y of [min,max])add((target-c-b*y)/a,y);}if(hits.length>=2){svg.append(svgEl('line',{x1:sx(hits[0][0]),y1:sy(hits[0][1]),x2:sx(hits[1][0]),y2:sy(hits[1][1]),stroke:target===0?'#243e48':'#c18a27','stroke-width':target===0?2.5:2,'stroke-dasharray':target===0?'none':'7 5'}));const p=hits[1];svg.append(svgEl('text',{x:sx(p[0])+8,y:sy(p[1])+16,fill:target===0?'#243e48':'#9b6719'},'score '+target));}}
 for(const target of [-1,0,1])line(target);
 for(const row of model.training_examples){const x=sx(row.z[0]),y=sy(row.z[1]);if(row.is_support_example)svg.append(svgEl('circle',{cx:x,cy:y,r:9,fill:'none',stroke:'#172f39','stroke-width':2}));const shape=row.numeric_label===-1?svgEl('circle',{cx:x,cy:y,r:4,fill:'#3a78a5'}):svgEl('rect',{x:x-4,y:y-4,width:8,height:8,fill:'#b84a5c'});const title=svgEl('title',{},'Glucose '+row.fasting_glucose_mg_dl+', BMI '+row.bmi+', y='+row.numeric_label+', alpha='+row.alpha.toFixed(5));shape.append(title);svg.append(shape);}
 if(project){svg.append(svgEl('line',{x1:sx(result.z[0]),y1:sy(result.z[1]),x2:sx(project[0]),y2:sy(project[1]),stroke:'#bd7b0f','stroke-width':2.5,'stroke-dasharray':'5 4'}));svg.append(svgEl('circle',{cx:sx(project[0]),cy:sy(project[1]),r:4,fill:'white',stroke:'#bd7b0f','stroke-width':2}));}
 const x=sx(result.z[0]),y=sy(result.z[1]);svg.append(svgEl('polygon',{points:[ [x,y-10],[x+10,y],[x,y+10],[x-10,y] ].map(p=>p.join(',')).join(' '),fill:'#dda531',stroke:'#8b5f13','stroke-width':2}));svg.append(svgEl('text',{x:Math.min(x+15,540),y:Math.max(top+15,y-15),fill:'#845813','font-weight':700},'Input: '+(result.numeric_label===1?'+1':'−1')));
 svg.append(svgEl('rect',{x:left,y:top,width:size,height:size,fill:'none',stroke:'#b8cac3'}));svg.append(svgEl('text',{x:left+size/2,y:625,'text-anchor':'middle',fill:'#172f39'},'Standardized fasting glucose (z₁)'));svg.append(svgEl('text',{transform:'translate(22 300) rotate(-90)','text-anchor':'middle',fill:'#172f39'},'Standardized BMI (z₂)'));
}
function addLine(parent,text){const p=document.createElement('p');p.textContent=text;parent.append(p);}
function update(){try{const glucose=Number($('glucose').value),bmi=Number($('bmi').value),r=SimpleSvm.predict(glucose,bmi,model);lastResult=r;$('error').textContent='';$('result').replaceChildren();$('result').append(document.createTextNode('Binary prediction'));const strong=document.createElement('strong');strong.textContent=r.zone;$('result').append(strong);$('result').append(document.createTextNode('Score '+r.score.toFixed(4)+' • '+(r.inside_margin?'Inside the margin':'Outside the margin')));$('score-details').replaceChildren();addLine($('score-details'),'z₁ = ('+glucose+' − '+model.means[0].toFixed(3)+') / '+model.scales[0].toFixed(3)+' = '+r.z[0].toFixed(4));addLine($('score-details'),'z₂ = ('+bmi+' − '+model.means[1].toFixed(3)+') / '+model.scales[1].toFixed(3)+' = '+r.z[1].toFixed(4));addLine($('score-details'),'score = '+model.weights[0].toFixed(4)+' × z₁ + '+model.weights[1].toFixed(4)+' × z₂ + '+model.bias.toFixed(4)+' = '+r.score.toFixed(4));addLine($('score-details'),'score '+(r.score>=0?'≥ 0 → class +1':'< 0 → class −1'));addLine($('score-details'),'Signed distance = score / ||w|| = '+(r.signed_distance===null?'undefined (zero weights)':r.signed_distance.toFixed(4)+' standardized units'));drawGraph(r);}catch(error){$('error').textContent=error.message;}}
$('prediction-form').addEventListener('submit',e=>{e.preventDefault();update();});
$('download-graph').addEventListener('click',()=>{const copy=$('svm-graph').cloneNode(true);copy.setAttribute('xmlns',NS);copy.prepend(svgEl('style',{},'text{font-family:Arial,sans-serif;font-size:13px}'));const url=URL.createObjectURL(new Blob([new XMLSerializer().serializeToString(copy)],{type:'image/svg+xml'})),link=document.createElement('a');link.href=url;link.download='linear-svm-decision.svg';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});
fetch('model.json').then(r=>{if(!r.ok)throw Error('Cannot load model. Run python train_model.py.');return r.json();}).then(data=>{model=data;const supports=model.training_examples.filter(row=>row.is_support_example);addLine($('training-details'),'Training points: '+model.training_examples.length+' • Support vectors: '+supports.length);addLine($('training-details'),'Training accuracy: '+(model.training_accuracy*100).toFixed(1)+'% (training data only)');addLine($('training-details'),'Margin width: '+(model.margin_width===null?'undefined':model.margin_width.toFixed(4)+' standardized units'));addLine($('training-details'),'Solver converged: '+model.converged+' • KKT violation: '+model.kkt_violation.toExponential(2));$('parameters').textContent='Current training parameters: '+JSON.stringify(model.parameters);const head=$('supports').createTHead().insertRow();for(const text of ['Glucose (mg/dL)','BMI','Class y','Dual α','y × score']){const th=document.createElement('th');th.textContent=text;head.append(th);}const body=$('supports').createTBody();for(const row of supports){const tr=body.insertRow();for(const value of [row.fasting_glucose_mg_dl,row.bmi,row.numeric_label,row.alpha.toFixed(6),(row.numeric_label*row.score).toFixed(6)])tr.insertCell().textContent=value;}for(const button of document.querySelectorAll('button'))button.disabled=false;update();}).catch(error=>{$('error').textContent=error.message;$('result').textContent='Model unavailable';});
